INSERT INTO hospedes(nome,email,telefone) VALUES ('Ana Oliveira','ana@email.test','86999990001'),('Bruno Santos','bruno@email.test','86999990002'),('Carla Mendes','carla@email.test','86999990003') ON CONFLICT(email) DO NOTHING;
INSERT INTO reservas(id_hospede,data_checkin,data_checkout,valor_diaria,status) SELECT h.id_hospede,v.data_checkin,v.data_checkout,v.valor_diaria,'ATIVA' FROM (VALUES ('ana@email.test',DATE '2026-10-10',DATE '2026-10-13',250.00::numeric),('bruno@email.test',DATE '2026-10-15',DATE '2026-10-18',300.00::numeric),('carla@email.test',DATE '2026-11-05',DATE '2026-11-07',200.00::numeric)) AS v(email,data_checkin,data_checkout,valor_diaria) JOIN hospedes h USING(email) WHERE NOT EXISTS(SELECT 1 FROM reservas r WHERE r.id_hospede=h.id_hospede AND r.data_checkin=v.data_checkin AND r.data_checkout=v.data_checkout);
